FORCEINLINE VectorRegister4Float VectorReciprocalSqrtAccurate(VectorRegister4Float Vec)
{
	return VectorReciprocalSqrt(Vec);
}

FORCEINLINE VectorRegister4Double VectorReciprocalSqrtAccurate(VectorRegister4Double Vec)
{
	return VectorReciprocalSqrt(Vec);
}

FORCEINLINE VectorRegister4Double VectorQuaternionRotateVector(VectorRegister4Double Quat, VectorRegister4Double VectorW0)
{
	const VectorRegister4Double QW = VectorReplicate(Quat, 3);
	VectorRegister4Double T = VectorCross(Quat, VectorW0);
	T = VectorAdd(T, T);
	const VectorRegister4Double VTemp0 = VectorMultiplyAdd(QW, T, VectorW0);
	const VectorRegister4Double VTemp1 = VectorCross(Quat, T);
	const VectorRegister4Double Rotated = VectorAdd(VTemp0, VTemp1);
	return Rotated;
}

/**
 * Rotate a vector using the inverse of a unit Quaternion (rotation in the opposite direction).
 *

FORCEINLINE VectorRegister4Double VectorDot4(VectorRegister4Double Vec1, VectorRegister4Double Vec2)
{
	VectorRegister2Double A, B;
	A = vmulq_f64(Vec1.XY, Vec2.XY);
	B = vfmaq_f64(A, Vec1.ZW, Vec2.ZW);
	A = vextq_f64(B, B, 1);
	VectorRegister4Double Temp;
	Temp.XY = vaddq_f64(A, B);
	Temp.ZW = Temp.XY;
	return Temp;
}

